import * as T from './vendor/three.module.min.js';
export function createCinematicWorld(parent){
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};
let renderer;try{renderer=new T.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'});}catch{return {update(){}}}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;
const holder=document.createElement('div');holder.className='cinematic-world';holder.setAttribute('aria-hidden','true');holder.append(renderer.domElement);parent.append(holder);
const scene=new T.Scene();scene.background=new T.Color('#050d17');scene.fog=new T.FogExp2('#07141f',.022);const camera=new T.PerspectiveCamera(57,innerWidth/innerHeight,.1,240);
scene.add(new T.HemisphereLight(0xbddaff,0x1b1110,2.1));const key=new T.PointLight(0xffd69c,90,45,1.5),rim=new T.PointLight(0x65c5eb,65,50,1.5);scene.add(key,rim);
const metal=new T.MeshStandardMaterial({color:0x122332,metalness:.75,roughness:.38}),dark=new T.MeshStandardMaterial({color:0x07121d,metalness:.65,roughness:.3}),gold=new T.MeshStandardMaterial({color:0xeac184,emissive:0xa75c1b,emissiveIntensity:.7,metalness:.75,roughness:.23});
const amber=new T.MeshBasicMaterial({color:0xffcf87}),blue=new T.MeshBasicMaterial({color:0x67c6df});
function box(w,h,d,mat,x,y,z,group=scene){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),mat);mesh.position.set(x,y,z);group.add(mesh);return mesh}
box(24,.15,240,metal,0,-3.1,-100);box(.3,18,240,dark,-9,5,-100);box(.3,18,240,dark,9,5,-100);
const lights=[];
for(let i=0;i<24;i++){const z=12-i*9;for(const side of [-1,1]){box(.32,11,.45,metal,side*8.7,2,z);box(.045,9,.05,i%3?blue:amber,side*8.48,1.5,z);box(.06,.035,8.6,i%3?blue:amber,side*6.8,-2.96,z-4.3);}box(17.4,.25,.45,metal,0,7.4,z);box(17,.035,.06,blue,0,7.22,z);}
// Door recesses are real three-dimensional structures the camera passes.
const doors=[];for(let i=0;i<9;i++){const group=new T.Group(),z=-i*9;group.position.set(6,0,z);scene.add(group);box(3.8,6.8,.4,metal,0,.3,0,group);box(3.25,6.2,.43,dark,0,.3,.08,group);const strips=[];for(const x of [-1.7,1.7])strips.push(box(.065,6.45,.08,amber,x,.3,.35,group));strips.push(box(3.45,.065,.08,amber,0,3.52,.35,group));const inner=box(2.8,5.6,.03,new T.MeshBasicMaterial({color:0x80c9e0,transparent:true,opacity:.035}),0,.3,.32,group);doors.push({group,strips,inner});}
// Keep the supplied image as the entrance and as an illuminated architectural backdrop.
const loader=new T.TextureLoader();let ready=false;loader.load('assets/experience-corridor.jpg',texture=>{texture.colorSpace=T.SRGBColorSpace;const mat=new T.MeshBasicMaterial({map:texture,transparent:true});const plate=new T.Mesh(new T.PlaneGeometry(28,42),mat);plate.position.set(0,3,-25);scene.add(plate);photo=plate;ready=true;parent.classList.add('world-ready');},undefined,()=>{});let photo;
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d'),g=x.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'#fff4d7');g.addColorStop(.08,'#ffe0a3cc');g.addColorStop(.3,'#e4a34633');g.addColorStop(1,'#e4a34600');x.fillStyle=g;x.fillRect(0,0,128,128);return new T.CanvasTexture(c)}const glow=glowTexture();
for(let i=0;i<25;i++){const sprite=new T.Sprite(new T.SpriteMaterial({map:glow,color:i%3?0x73c7ed:0xffcc87,blending:T.AdditiveBlending,transparent:true,depthWrite:false}));sprite.position.set(i%2?7.8:-7.8,2,8-i*8);sprite.scale.set(5,5,1);scene.add(sprite);lights.push(sprite)}
// The golden route physically recedes into the same corridor as the frames.
const route=[];for(let j=0;j<500;j++){const z=12-j*.45;route.push(new T.Vector3(Math.sin(z*.1)*1.8,-2.92,z));}const curve=new T.CatmullRomCurve3(route),tube=new T.Mesh(new T.TubeGeometry(curve,380,.025,5,false),amber);scene.add(tube);const signal=new T.Sprite(new T.SpriteMaterial({map:glow,blending:T.AdditiveBlending,depthWrite:false}));signal.scale.set(2,2,1);scene.add(signal);
const particlePositions=new Float32Array(600*3);for(let j=0;j<600;j++){particlePositions[j*3]=Math.sin(j*2.399)*8;particlePositions[j*3+1]=(j%37)/37*10-2;particlePositions[j*3+2]=12-(j%223);}const pg=new T.BufferGeometry();pg.setAttribute('position',new T.BufferAttribute(particlePositions,3));const dust=new T.Points(pg,new T.PointsMaterial({size:.045,color:0xe6ce9c,transparent:true,opacity:.65,depthWrite:false}));scene.add(dust);
// Gallery frames have thickness, a luminous edge, and a subdued floor reflection.
const assets=['kist','fusionhacks','founderforge','set','ioai'],frames=[];
assets.forEach((name,i)=>{const group=new T.Group();group.position.set(3.5,1.2,-110-i*15);scene.add(group);const frame={group,reflection:null};frames.push(frame);loader.load('assets/award-'+name+'.png',texture=>{texture.colorSpace=T.SRGBColorSpace;const ratio=texture.image.width/texture.image.height,w=Math.min(7,5.6*ratio),h=w/ratio;box(w+.32,h+.32,.3,gold,0,0,-.12,group);box(w+.14,h+.14,.32,dark,0,0,.02,group);const image=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:texture}));image.position.z=.2;group.add(image);const refl=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:texture,transparent:true,opacity:.12,depthWrite:false}));refl.rotation.x=Math.PI;refl.position.set(group.position.x,-7.2,group.position.z);scene.add(refl);frame.reflection=refl;const halo=new T.Sprite(new T.SpriteMaterial({map:glow,color:0xe2b469,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));halo.position.z=-.5;halo.scale.set(w*2,h*2,1);group.add(halo);});});
// A large light threshold separates experience from recognition without a cut.
const gateway=new T.Group();gateway.position.z=-97;scene.add(gateway);for(const x of [-5,5])box(.12,11,.2,amber,x,2,0,gateway);box(10,.12,.2,amber,0,7.5,0,gateway);
let timeline=0,paused=false,time=0,last=0,visible=false,mx=0;addEventListener('pointermove',e=>{mx=(e.clientX/innerWidth-.5)*.5},{passive:true});function size(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',size);
function frame(ms){requestAnimationFrame(frame);const dt=Math.min(.04,(ms-last)/1000);last=ms;if(!visible||!ready||document.hidden)return;if(!paused)time+=dt;const t=timeline,mobile=innerWidth<760;let x=0,y=.4,z=16,lookX=0,lookY=.3,lookZ=-20;
if(t<26){const u=ease((t-22.05)/3.95);z=16-u*9;photo.material.opacity=1-ease((t-24)/2);}
else if(t<39.4){const p=Math.max(0,(t-26)/1.5),i=Math.min(8,Math.floor(p)),f=p-i,move=i+ease((f-.55)/.45);z=7-move*9;x=mobile?-.4:-1.6;lookX=mobile?2:3.2;lookY=.2;lookZ=z-16;photo.material.opacity=0;doors.forEach((door,j)=>{door.inner.material.opacity=j===i?.22+.06*Math.sin(time):.025;door.strips.forEach(s=>s.material=j===i?amber:blue)});}
else{photo.material.opacity=0;const p=clamp((t-42)/9.2)*4,i=Math.min(4,Math.floor(p)),f=p-i,travel=i+(i<4?ease((f-.6)/.4):0),entry=ease((t-39.4)/2.6);z=T.MathUtils.lerp(-74,-98-travel*15,entry);x=T.MathUtils.lerp(-1.6,mobile?0:-1.2,entry);lookX=mobile?0:.8;lookY=mobile?-.7:.35;lookZ=z-15;frames.forEach((item,j)=>{item.group.position.x=mobile?0:3.5;item.group.position.y=mobile?1.1:1.2;item.group.rotation.y=paused?0:Math.sin(time*.35+j)*.035;item.group.position.y+=(paused?0:Math.sin(time*.65+j)*.08);if(item.reflection)item.reflection.position.x=item.group.position.x;});}
if(!paused){x+=Math.sin(time*.2)*.08+mx*.3;y+=Math.sin(time*.35)*.035}camera.position.set(x,y,z);camera.lookAt(lookX,lookY,lookZ);key.position.set(x+2,4,z-5);rim.position.set(-5,1,z-12);signal.position.copy(curve.getPoint(clamp((16-z+(paused?0:Math.sin(time)*2))/225)));dust.rotation.z=paused?0:Math.sin(time*.1)*.006;lights.forEach((l,i)=>l.material.opacity=paused?.55:.45+Math.sin(time*.8+i)*.15);renderer.render(scene,camera);
}requestAnimationFrame(frame);
return {update(t,stop){timeline=t;paused=stop;visible=t>22.05;holder.style.visibility=visible?'visible':'hidden';holder.style.opacity=ease((t-22.05)/1);}};
}
